// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"ja","term":"完全希薄化後時価総額（FDV）","aka":["FDV","Fully diluted valuation"],"short":"完全希薄化後時価総額（FDV）とは、トークンの現在価格に最大供給量（または総供給量）を掛けた値で、将来すべてのトークンが流通した場合の評価額を示します。","body":[["通常の",["時価総額","market-capitalization"],"が「今流通している分」だけを数えるのに対し、FDVはまだロックされている分や将来発行される予定の分も含めて計算します。新しく",["上場","token-listing"],"したトークンは",["流通量","circulating-supply"],"が全体の一部にとどまることが多く、時価総額とFDVの差が大きくなりがちです。"],["この差は将来の売り圧力の目安になります。チームや初期投資家に割り当てられたトークンは、ロック期間が終わると段階的に",["アンロック","token-unlock"],"され、市場に出てくる可能性があります。需要が同じなら、供給が増えるほど1枚あたりの価格には下押し圧力がかかります。"],"最大供給量が決まっていないトークンでは、FDVの計算に総供給量を使うなど、データサイトによって定義が異なります。数字を比べるときは、どの供給量を使っているかを確認しましょう。"],"example":"例えば、トークンXの価格が0.5ドル、流通量が2億枚、最大供給量が20億枚だとします。時価総額は0.5 × 2億 = 1億ドル、FDVは0.5 × 20億 = 10億ドルです。流通しているのは全体の10%だけで、残りの18億枚が今後数年かけて市場に出てくる可能性があります。","mistakes":["時価総額だけを見て割安だと判断し、FDVとの大きな差を見落とすこと。","アンロックのスケジュールを確認せずに、上場直後の低流通トークンを長期保有すること。","FDVを「将来到達する目標の評価額」のように解釈すること。"],"faq":[{"q":"FDVと時価総額の差が大きいとどうなりますか？","a":"将来のアンロックで供給が大きく増える可能性があることを示します。需要が追いつかなければ、価格に下押し圧力がかかりやすくなります。"},{"q":"FDVが高いトークンは避けるべきですか？","a":"一概には言えません。アンロックの時期や量、誰が受け取るのか、プロジェクトの実需などをあわせて判断することが大切です。"}],"title":"FDV（完全希薄化後時価総額）とは？時価総額との違い","description":"FDV（完全希薄化後時価総額）の意味と計算方法、時価総額との違い、アンロックとの関係を具体例で解説します。","related":[["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"],["circulating-supply","流通供給量","流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。"],["token-unlock","トークンアンロック","トークンアンロックとは、チームや投資家などに配分されロックされていたトークンが、決められたスケジュールに従って売却や移転できるようになることです。"],["tokenomics","トークノミクス","トークノミクスとは、暗号資産トークンの供給量、配分、発行スケジュール、用途、焼却などをまとめた経済設計の全体像のことです。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"ja","term":"マイニング（採掘）","aka":["採掘","Mining"],"short":"マイニング（採掘）とは、プルーフ・オブ・ワークのブロックチェーンで計算処理を行って取引をブロックにまとめ、その報酬として新規発行の暗号資産と手数料を受け取る活動です。","body":[["マイナーは専用の機械でハッシュ計算を繰り返し、最初に条件を満たす答えを見つけるとブロックを追加できます。その対価として、ブロック報酬とブロック内の取引手数料を受け取ります。",["ビットコイン","bitcoin"],"のマイニングは現在、ASICと呼ばれる専用チップを使う大規模事業者が中心です。"],["個人が単独でブロックを見つける確率は非常に低いため、多くのマイナーは「マイニング",["プール","liquidity-pool"],"」に参加し、計算力に応じて報酬を分け合います。収益は、",["暗号資産","cryptocurrency"],"の価格、ネットワーク全体の",["ハッシュレート","hash-rate"],"、電気代、機器の性能によって大きく変わります。"],"「クラウドマイニング」と称して、出資すれば毎日一定の報酬が得られると勧誘する案件には注意が必要です。実際には採掘をしていない詐欺的なケースもあります。運営会社の実態や、報酬が固定で約束されていないかを確認しましょう。"],"example":"例えば、消費電力3,000Wのマイニング機を1日24時間動かすと、電力量は3kW × 24時間 = 72kWhです。電気代が1kWhあたり30円なら、1日2,160円かかります。その機械で得られる報酬が1日2,000円相当なら、機器代を考える前に電気代だけで毎日160円の赤字になります。","mistakes":["電気代や機器の償却費を計算に入れず、採掘報酬だけで利益を見積もること。","「元本保証」「毎日固定報酬」をうたうクラウドマイニングに出資すること。","半減期で報酬が減ることを考えずに、長期の収益計画を立てること。"],"faq":[{"q":"個人でもビットコインのマイニングはできますか？","a":"技術的には可能ですが、専用機と安い電力を持つ大規模事業者と競争することになるため、個人で利益を出すのは難しいのが一般的です。"},{"q":"マイニングとステーキングの違いは何ですか？","a":"マイニングは計算力と電力を使うPoWの仕組みで、ステーキングは暗号資産を預けて検証に参加するPoSの仕組みです。"}],"title":"マイニング（採掘）とは？仕組みと収益の考え方","description":"暗号資産のマイニングの仕組み、マイニングプール、電気代を含めた収益の考え方、詐欺的な勧誘の見分け方を解説します。","related":[["proof-of-work","プルーフ・オブ・ワーク（PoW）","プルーフ・オブ・ワーク（PoW）とは、マイナーが大量の計算で競争し、最初に条件を満たす答えを見つけた者が新しいブロックを追加できるコンセンサスの仕組みです。"],["hash-rate","ハッシュレート","ハッシュレートとは、プルーフ・オブ・ワーク（PoW）のブロックチェーンでマイニング機器が1秒間に計算できるハッシュの回数のことで、ネットワーク全体の計算力を表します。"],["bitcoin-halving","ビットコイン半減期","ビットコイン半減期とは、21万ブロックごと（約4年ごと）に、マイナーが受け取る新規発行のブロック報酬が半分になるイベントのことです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"ja","term":"バリデーター（検証者）","aka":["Validator","検証者","バリデータ"],"short":"バリデーターとは、プルーフ・オブ・ステークのブロックチェーンで暗号資産をステークし、ブロックの提案や取引の検証を行うネットワーク参加者のことです。","body":[["バリデーターは",["ノード","node"],"ソフトウェアを常に稼働させ、順番が回ってきたらブロックを提案し、他のバリデーターが提案したブロックが正しいかを投票で確認します。正しく働くと報酬が得られ、オフラインになると報酬が減ったり小さなペナルティを受けたりします。"],["二重署名のような重大な違反をすると、",["ステーク","staking"],"の一部が没収される「スラッシング」の対象になります。そのため、バリデーターの運用には安定したサーバー、鍵の安全な管理、ソフトウェアの更新といった技術的な対応が欠かせません。"],"多くのチェーンでは、一般の保有者が自分の資産をバリデーターに委任（デリゲート）し、報酬の一部を受け取れます。委任先によって手数料率や稼働実績が異なるため、選ぶときは手数料、稼働率、過去のスラッシング履歴を確認しましょう。"],"example":"例えば、あるバリデーターが年間1,000 SOLの報酬を生み出し、手数料率を8%に設定しているとします。バリデーターの取り分は80 SOLで、委任者全体には920 SOLが配分されます。あなたの委任額がそのバリデーターへの委任総額の1%なら、受け取る報酬は約9.2 SOLです。","mistakes":["手数料率の低さだけで委任先を選び、稼働率や過去のスラッシング歴を確認しないこと。","委任すると資産の所有権までバリデーターに移ると誤解すること。","自分で運用する際、同じ鍵を複数のサーバーで同時に動かして二重署名を起こすこと。"],"faq":[{"q":"バリデーターとマイナーの違いは何ですか？","a":"マイナーはPoWで計算力を使ってブロックを作り、バリデーターはPoSでステークを担保にブロックを提案・検証します。"},{"q":"委任した資産をバリデーターに持ち逃げされることはありますか？","a":"多くのPoSチェーンの委任では、資産の所有権は委任者に残り、バリデーターが勝手に引き出すことはできません。ただし、スラッシングが起きると委任分も減る仕組みのチェーンがあります。"}],"title":"バリデーターとは？PoSでの役割と報酬の仕組み","description":"バリデーターの役割、報酬とスラッシングの仕組み、委任（デリゲート）先の選び方をPoSの仕組みとあわせて解説します。","related":[["proof-of-stake","プルーフ・オブ・ステーク（PoS）","プルーフ・オブ・ステーク（PoS）とは、暗号資産を担保として預け入れ（ステーク）したバリデーターが、ブロックの提案と検証を担うコンセンサスの仕組みです。"],["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"],["restaking","リステーキング","リステーキングとは、すでにステーキングしている資産やリキッドステーキングトークンを、別のサービスの安全性確保にも再利用し、追加の報酬を得ようとする仕組みです。"],["blockchain","ブロックチェーン","ブロックチェーンとは、取引記録を「ブロック」にまとめて時系列に鎖のようにつなぎ、多数のコンピューターで共有・検証する分散型の台帳技術です。"]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"ja","term":"取引ペア（通貨ペア）","aka":["通貨ペア","Trading pair"],"short":"取引ペアとは、BTC/USDTやETH/JPYのように、どの資産をどの資産と交換するかを示す組み合わせのことで、取引所の売買はすべてペア単位で行われます。","body":[["取引ペアの左側をベース通貨、右側をクオート通貨（決済通貨）と呼びます。",["BTC","bitcoin"],"/USDTの価格が60,000と表示されていれば、1 BTCを買うのに60,000 USDTが必要という意味です。BTC/USDTで「買い」を選ぶと、USDTを支払ってBTCを受け取ります。"],["海外の取引所ではUSDTやUSDCなどの",["ステーブルコイン","stablecoin"],"建てのペアが中心で、日本国内の取引所では円建て（BTC/JPYなど）が中心です。同じ銘柄でも、ペアによって",["出来高","trading-volume"],"や板の厚さが大きく違うため、取引量の多いペアを選ぶと",["スプレッド","bid-ask-spread"],"や",["スリッページ","slippage"],"を抑えやすくなります。"],"目的のペアがない場合は、2回の取引を経由することになります。例えばある小型トークンがETH建てでしか取引されていなければ、まずUSDTでETHを買い、そのETHでトークンを買う必要があり、手数料も2回かかります。"],"example":"例えば、SOL/USDTが150、BTC/USDTが60,000のとき、SOL/BTCの理論上の価格は150 ÷ 60,000 = 0.0025です。3 SOLを売ってBTCを手に入れたい場合、SOL/BTCペアがあれば1回の取引で約0.0075 BTCになります。ペアがなければSOLをUSDTに売り、そのUSDTでBTCを買う2回の取引になり、手数料が0.1%ずつなら合計で約0.2%のコストです。","mistakes":["ベース通貨とクオート通貨を逆に読み、買いと売りを取り違えること。","出来高の少ないペアを選び、スプレッドの分だけ不利な価格で約定すること。","USDT建てとUSDC建てなど、似たペアの価格差を確認しないこと。"],"faq":[{"q":"BTC/USDTはどう読めばいいですか？","a":"1 BTCが何USDTかを表すペアです。左のBTCが売買の対象、右のUSDTが価格を表す通貨です。"},{"q":"円建てとUSDT建てのどちらで取引すべきですか？","a":"使う取引所と、手元にある資産によって変わります。同じ銘柄なら、出来高が多く板が厚いペアのほうが取引コストを抑えやすいです。"}],"title":"取引ペア（通貨ペア）とは？BTC/USDTの読み方","description":"暗号資産の取引ペア（通貨ペア）の意味、BTC/USDTの読み方、ペアの選び方と手数料の違いを具体例で解説します。","related":[["spot-trading","現物取引（スポット取引）","現物取引（スポット取引）とは、暗号資産をその時点の価格で実際に売買し、買った資産をそのまま受け取って保有する取引のことです。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"初めての現物取引：100から0.002 BTCへ"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"ja","term":"OCO注文","aka":["OCO","One Cancels the Other"],"short":"OCO注文とは、2つの注文を同時に出し、どちらか一方が約定するともう一方が自動的に取り消される注文方法です。","body":[["OCOは「One Cancels the Other（一方が他方を取り消す）」の略です。典型的な使い方は、保有中のポジションに対して、上に利益確定の指値、下に",["損切り","stop-loss"],"の逆指値を同時に置くことです。価格がどちらかに達すれば決済され、残った注文は自動で消えます。"],"利点は、注文の消し忘れを防げることです。利確と損切りを別々に出すと、片方が約定した後にもう片方が残り、意図しない新規ポジションを持ってしまうおそれがあります。OCOならこの問題が起きません。上抜けたら買う、下抜けたら売るといった、ブレイクアウト狙いの使い方もできます。",["注意点として、OCOの損切り側は",["ストップリミット","stop-limit-order"],"形式になっている取引所が多く、急変時に約定しないことがあります。また、OCOで出す2つの注文は同じ数量を対象にするのが一般的です。新規注文が約定したら決済注文を出すIFDや、IFDとOCOを組み合わせたIFDOCOも、日本の取引所でよく使われます。"]],"example":"例えば、XRPを0.60ドルで1,000枚保有しているとします。OCOで「0.69ドルで売る指値」と「0.56ドルで発動する売りのストップ」を設定すると、上なら1,000 × 0.09 = 90ドルの利益、下なら1,000 × 0.04 = 40ドルの損失（約定価格のずれと手数料を除く）で決済されます。0.69ドルで売れた時点で、ストップ注文は自動で取り消されます。","mistakes":["OCOの損切り側がストップリミットであることを知らず、急落時に約定しないこと。","利確と損切りを別々の注文で出し、片方の約定後にもう片方を取り消し忘れること。","保有数量より多い数量でOCOを設定しようとして、注文が通らない理由が分からないこと。"],"faq":[{"q":"OCOとIFDOCOの違いは何ですか？","a":"OCOは2つの決済注文を同時に出す方法です。IFDOCOは、新規注文が約定したら自動的にOCOの決済注文が有効になる、エントリーから決済までを一度に設定する方法です。"},{"q":"OCO注文はどの取引所でも使えますか？","a":"多くの大手取引所で使えますが、対応する商品や注文画面での名称は取引所ごとに異なります。"}],"title":"OCO注文とは？仕組みと利確・損切りへの使い方","description":"OCO注文の仕組み、利益確定と損切りを同時に設定する使い方、IFDやIFDOCOとの違いを具体例で解説します。","related":[["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["risk-reward-ratio","リスクリワードレシオ（損益比率）","リスクリワードレシオとは、1回の取引で想定する損失額（リスク）と利益額（リワード）の比率のことで、例えば損失100に対して利益200なら1対2と表します。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"成行、指値、キャンセル：それぞれ何を解決するのか？"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"ja","term":"ポストオンリー注文","aka":["ポストオンリー","メイカーオンリー","Post-only"],"short":"ポストオンリー注文とは、板に並ぶメイカー注文としてのみ受け付けられ、すぐに約定してテイカーになる場合は自動で取り消される指値注文の設定です。","body":[["通常の",["指値注文","limit-order"],"でも、現在の最良価格を越える価格を指定するとすぐに約定し、",["テイカー手数料","maker-taker-fees"],"がかかります。ポストオンリーを付けると、そうした注文は約定せずに取り消される（取引所によっては価格を調整して板に置かれる）ため、メイカーとして約定することが保証されます。"],"主な目的は手数料の節約です。多くの取引所ではメイカー手数料がテイカー手数料より低く設定されているため、取引回数の多いトレーダーや自動売買ボット、マーケットメイクを行う人がよく使います。","欠点は、急いで約定させたい場面には向かないことです。価格が動いている最中に出すと注文が取り消され、チャンスを逃すことがあります。名称（Post Only、メイカーオンリーなど）や取り消し時の挙動は取引所ごとに異なるため、注文画面の説明を確認しましょう。"],"example":"例えば、メイカー手数料0.02%、テイカー手数料0.06%の先物で、月に合計200万ドル分を取引するとします。すべてテイカーなら手数料は1,200ドル、すべてメイカーなら400ドルで、差は月800ドルです。ポストオンリーを使えば、指値のつもりがうっかりテイカーとして約定してしまう注文を防げます。","mistakes":["素早く約定させたい損切りやエントリーにポストオンリーを使い、注文が取り消されること。","最良価格を越える価格でポストオンリーを出し、なぜ注文が消えたのか分からなくなること。","手数料の差だけを見て、約定しないことによる機会損失を考えないこと。"],"faq":[{"q":"ポストオンリー注文が取り消されるのはなぜですか？","a":"指定した価格では既存の注文とすぐに約定し、テイカーになってしまうためです。最良価格より手前の価格で出し直すと板に並びます。"},{"q":"ポストオンリーは成行注文にも使えますか？","a":"使えません。成行注文は必ずテイカーになるため、ポストオンリーは指値注文にだけ付けられる設定です。"}],"title":"ポストオンリー注文とは？メイカー手数料を確実にする方法","description":"ポストオンリー注文の仕組み、メイカー手数料を確保できる理由、注文が取り消されるケースと注意点を解説します。","related":[["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["time-in-force","執行条件（GTC・IOC・FOK）","執行条件（タイムインフォース）とは、注文をいつまで有効にし、約定しなかった分をどう扱うかを決める設定で、代表的なものにGTC・IOC・FOKがあります。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"成行、指値、キャンセル：それぞれ何を解決するのか？"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"ja","term":"メイカー手数料・テイカー手数料（Maker/Taker）","aka":["メイカー手数料","テイカー手数料","メイカー・テイカー","maker taker fee"],"short":"メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。","body":[[["板（オーダーブック）","order-book"],"で成立する取引には必ず2つの立場があります。先に",["指値注文","limit-order"],"を出して板に並んで待つ側がメイカーで、市場に厚みを加えます。出した瞬間に既存の注文とぶつかって約定する側がテイカーで、板の厚みを消費します。",["成行注文","market-order"],"はほぼ必ずテイカーになり、すぐに約定しない価格の指値注文は通常メイカーになります。"],["多くの取引所は",["流動性","liquidity"],"を増やすため、メイカー手数料をテイカー手数料より低く設定しています。",["取引量","trading-volume"],"の多い",["VIPランク","vip-tier"],"やマーケットメイカー向けには、メイカー手数料がマイナス（約定すると逆に受け取れる）になる例もあります。料率は取引所、現物か先物か、会員ランク、取引所トークンでの割引の有無によって変わるため、注文前に各取引所の手数料ページで確認してください。"],"取引回数が多い人ほど、この差は大きく効いてきます。確実にメイカーとして約定させたい場合は、ポストオンリー（Post Only）を使うと、即時約定してしまう注文は自動でキャンセルされます。"],"example":"ある取引所の先物でメイカー手数料が0.02%、テイカー手数料が0.05%だとします。想定元本8,000 USDTのポジションを指値でメイカー約定させると手数料は1.6 USDT、成行でテイカー約定させると4 USDTです。決済時にも同じだけかかるので、往復ではメイカー3.2 USDT、テイカー8 USDTになります。これを月40往復すると、差額は（8−3.2）×40＝192 USDTです。","mistakes":["指値注文なら必ずメイカー扱いだと思い込み、板の反対側を食う価格で出してテイカー手数料を払ってしまう。","取引所をメイカー手数料だけで比較し、自分の注文の大半が成行注文であることを見落とす。","エントリー時の手数料だけを計算し、決済や逆指値の発動で発生するテイカー手数料を忘れる。"],"faq":[{"q":"メイカーとテイカーはどちらが手数料が安いですか？","a":"多くの取引所ではメイカーのほうが安く設定されています。板に流動性を提供しているためで、上位ランクではメイカー手数料がマイナスになることもあります。"},{"q":"成行注文はメイカーとテイカーのどちらですか？","a":"成行注文は板にある既存の注文と即座に約定するため、テイカーとして手数料がかかります。"},{"q":"確実にメイカー手数料で約定させる方法はありますか？","a":"ポストオンリー（Post Only）を指定すると、即時約定する注文はキャンセルされるため、約定した場合は必ずメイカー扱いになります。"}],"title":"メイカー手数料・テイカー手数料とは？違いと節約のコツ","description":"メイカー手数料とテイカー手数料の違い、メイカーが安い理由、ポストオンリーで取引コストを抑える方法を具体例でわかりやすく解説します。","related":[["post-only-order","ポストオンリー注文","ポストオンリー注文とは、板に並ぶメイカー注文としてのみ受け付けられ、すぐに約定してテイカーになる場合は自動で取り消される指値注文の設定です。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["market-order","成行注文","成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。"],["vip-tier","VIPランク（手数料ティア）","VIPランクとは、取引所が利用者の取引量や資産残高に応じて設定する段階的な会員区分で、ランクが上がるほど取引手数料が安くなる仕組みです。"],["referral-code","紹介コード（手数料キャッシュバック）","紹介コードとは、取引所の口座開設時に入力することで、紹介者と新規利用者の双方に手数料の割引やキャッシュバックなどの特典が付与される仕組みです。"]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"画面に表示された価格が、なぜ約定価格と違うのか？"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"ja","term":"維持証拠金（メンテナンスマージン）","aka":["メンテナンスマージン","維持証拠金率","maintenance margin"],"short":"維持証拠金（メンテナンスマージン）とは、ポジションを持ち続けるために口座に残しておかなければならない最低限の証拠金で、これを下回ると強制ロスカット（清算）が始まります。","body":[["ポジションに",["含み損","unrealized-pnl"],"が出ると、証拠金の残り（証拠金残高）が減っていきます。この残高が維持証拠金を下回ると、取引所はそれ以上の損失を防ぐためにポジションを強制的に決済します。維持証拠金は、想定元本×維持証拠金率で計算され、維持証拠金率は銘柄やポジションの規模によって変わります。"],["判定には通常",["マーク価格","mark-price"],"が使われます。",["最終取引価格","last-price"],"が一瞬だけ大きく動いても、マーク価格が動かなければ清算されにくい仕組みです。また、ポジションが大きくなるほど維持証拠金率が上がる段階制を採用している取引所が多く、大きなポジションほど",["清算価格","liquidation-price"],"が建値に近づきます。"],["維持証拠金は",["当初証拠金","initial-margin"],"より低く設定されているため、その差が清算までの余裕です。証拠金を追加すれば清算価格を遠ざけられますが、根本的な対策は無理のない",["ポジションサイズ","position-sizing"],"にすることです。"]],"example":"分離マージンでBTCを60,000 USDTで1枚ロングし、20倍で当初証拠金3,000 USDTを入れたとします。維持証拠金率が0.5%なら、手数料を無視すると、価格Pで含み損（60,000−P）を引いた残高が0.005×Pと等しくなるところが清算価格です。3,000−（60,000−P）＝0.005P を解くと、P＝約57,290 USDTです。建値から約4.5%下がると清算されます。","mistakes":["証拠金がゼロになるまで清算されないと思い込み、維持証拠金のラインを考えない。","ポジションを大きくすると維持証拠金率も上がる段階制を見落とす。","最終取引価格で清算判定されると誤解し、マーク価格の動きを確認しない。"],"faq":[{"q":"維持証拠金を下回るとどうなりますか？","a":"強制ロスカット（清算）が始まり、ポジションが取引所によって決済されます。残った証拠金から清算手数料が差し引かれることもあります。"},{"q":"維持証拠金率はどこで確認できますか？","a":"取引所の契約仕様や証拠金のティア表で確認できます。銘柄やポジションの規模によって率が異なります。"}],"title":"維持証拠金とは？清算との関係と計算例","description":"維持証拠金（メンテナンスマージン）の意味、強制ロスカットが始まる仕組み、清算価格の計算方法を先物の具体例で解説します。","related":[["initial-margin","当初証拠金（イニシャルマージン）","当初証拠金（イニシャルマージン）とは、レバレッジをかけたポジションを新しく建てるときに、最低限差し入れる必要がある証拠金の額のことです。"],["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。"],["margin-call","マージンコール（追証）","マージンコールとは、損失によって証拠金が一定の水準を下回ったときに、取引所が追加の入金やポジションの縮小を求める警告や通知のことです。"],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"証拠金がゼロになる前に強制終了されるのはなぜか"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"ja","term":"リデュースオンリー注文（決済専用注文）","aka":["リデュースオンリー","決済専用","reduce-only","Reduce Only"],"short":"リデュースオンリー注文とは、既存のポジションを減らす方向にしか約定しない注文の設定で、意図せず反対方向の新規ポジションを建ててしまうことを防ぎます。","body":[[["先物取引","futures-contract"],"の一方向モードでは、",["ロング","long-and-short"],"を持った状態で売り注文を出すと、ロングを減らすと同時に、数量が多すぎた分は新しいショートになってしまうことがあります。リデュースオンリーを指定すると、その注文はポジションを閉じる・減らすためにしか使われず、保有量を超える部分は自動的に取り消されるか縮小されます。"],["特に役立つのが、利益確定や",["損切り","stop-loss"],"の注文をあらかじめ置いておく場面です。手動でポジションを一部決済した後に、元の数量で出していた利確注文が約定すると、意図しない反対ポジションができてしまいます。リデュースオンリーなら、その心配がありません。"],["多くの取引所では、ポジションに紐付けた利確・損切り（TP/SL）は自動的にリデュースオンリーとして扱われます。",["指値注文","limit-order"],"や逆指値注文で個別に出す場合は、チェックボックスで指定します。",["両建て","hedging"],"モードでの扱いや名称は取引所ごとに少し異なります。"]],"example":"ETHのロングを2 ETH持っていて、3,600 USDTに3 ETHの売りの指値を置いたとします。リデュースオンリーなしだと、約定時に2 ETHのロングが決済され、残りの1 ETHが新しいショートになります。リデュースオンリーを指定していれば、約定するのは2 ETHだけで、ポジションはゼロになって終わります。もし途中で手動で1 ETHを決済していれば、約定するのは残りの1 ETHだけです。","mistakes":["利確注文の数量を保有量より多く設定し、リデュースオンリーを付けずに反対ポジションを建ててしまう。","手動で一部決済した後、残っていた古い決済注文を取り消し忘れる。","新規エントリーの注文に誤ってリデュースオンリーを付け、注文が通らずに戸惑う。"],"faq":[{"q":"リデュースオンリーはどんなときに使いますか？","a":"利益確定や損切りの注文を事前に置くときに使います。数量が保有量を超えても、反対方向の新規ポジションにならないので安全です。"},{"q":"ポジションがないときにリデュースオンリー注文を出すとどうなりますか？","a":"減らすポジションがないため、注文が受け付けられないか、すぐに取り消されます。"}],"title":"リデュースオンリー注文とは？使い方とメリット","description":"リデュースオンリー（決済専用）注文の意味、意図しない反対ポジションを防ぐ仕組み、利確や損切りでの使い方を具体例で解説します。","related":[["take-profit","利益確定注文（テイクプロフィット）","利益確定注文（テイクプロフィット）とは、価格が目標の水準に達したときに自動で決済し、含み益を実際の利益として確定させる注文です。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["long-and-short","ロングとショート（買いポジション・売りポジション）","ロングとショートとは、価格の上昇で利益が出る買いのポジション（ロング）と、価格の下落で利益が出る売りのポジション（ショート）のことです。"]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"利確と損切りは計画であって、保険ではない"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"ja","term":"ウォレットアドレス","aka":["アドレス","入金アドレス","wallet address","受取アドレス"],"short":"ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。","body":[["アドレスの形式は",["ブロックチェーン","blockchain"],"ごとに異なります。",["ビットコイン","bitcoin"],"はbc1や1、3で始まるもの、",["イーサリアム","ethereum"],"やBNB Chainなどは0xで始まる42文字、トロンはTで始まるものが一般的です。"],["注意したいのは、同じ0xで始まるアドレスが複数のチェーンで使える点です。アドレス形式が同じでも、",["送金ネットワーク","blockchain-network"],"を間違えると相手の取引所で反映されないことがあります。"],"ブロックチェーンの送金は取り消せません。アドレスは必ずコピー＆ペーストで入力し、貼り付け後に先頭と末尾の数文字を目で照合します。初めての送金先には、少額でテスト送金するのが基本です。"],"example":["取引所からUSDTを5,000 USDT出金するとします。",["出金手数料","withdrawal-fee"],"が1回1 USDTだとして、まず10 USDTだけをテスト送金し、相手側に9 USDTが届いたことを確認します。そのうえで残りを送れば、アドレスやネットワークの間違いで失うリスクは最初の10 USDTに限られます。テスト分の手数料1 USDTは、全額を失うリスクと比べれば小さなコストです。"],"mistakes":["アドレスを手入力したり、確認せずに履歴からコピーしたりすること。","取引履歴に紛れ込んだ、よく似た偽アドレスに送金してしまうこと。","アドレスの形式が同じだからといって、送金ネットワークを確認しないこと。"],"faq":[{"q":"ウォレットアドレスを他人に教えても安全ですか？","a":"アドレスだけで資産を盗まれることはありません。ただし、そのアドレスの残高や取引履歴は誰でも見られるため、プライバシーには配慮しましょう。"},{"q":"アドレスを間違えて送金したら取り戻せますか？","a":"存在しないアドレスや無関係な人のアドレスに送った場合、基本的に取り戻せません。取引所のアドレスなら、その取引所のサポートに相談できる場合があります。"}],"title":"ウォレットアドレスとは？意味と送金前の確認方法","description":"ウォレットアドレスの意味、チェーンごとの形式の違い、誤送金を防ぐための確認手順とテスト送金のコツを解説します。","related":[["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"],["memo-tag","メモ／宛先タグ（Memo・Destination Tag）","メモ（宛先タグ）とは、XRPやXLMなど一部の暗号資産で、同じ入金アドレスを共有する利用者の中から受取人を特定するための追加の番号や文字列です。"],["address-poisoning","アドレスポイズニング","アドレスポイズニングとは、本物の送金先とよく似たアドレスから少額や0円の取引を送りつけ、取引履歴から偽アドレスをコピーさせて誤送金を誘う詐欺です。"],["withdrawal-whitelist","出金ホワイトリスト","出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"ja","term":"フィッシング詐欺","aka":["フィッシング","phishing","偽サイト詐欺"],"short":"フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。","body":[["代表的な手口は、公式に似せたドメインの偽サイト、検索広告の偽リンク、「アカウントが凍結されます」などと急がせるメールやSMS、SNSやTelegramの偽",["サポート","support-and-resistance"],"です。"],[["暗号資産","cryptocurrency"],"ならではの手口として、",["ウォレット","crypto-wallet"],"を接続させて悪意ある",["トークン承認","token-approval"],"や署名をさせるものがあります。この場合パスワードを盗まれなくても、署名1回で資産が抜き取られることがあります。"],["対策の基本は、公式サイトをブックマークして毎回そこから開くこと、届いたリンクを開かないこと、署名前にウォレットに表示される内容を読むことです。正規の取引所やウォレットが",["シードフレーズ","seed-phrase"],"を尋ねることはありません。"]],"example":["「",["エアドロップ","airdrop"],"対象です。48時間以内に受け取ってください」というDMが届き、リンク先にウォレットを接続すると、USDTの承認を求める画面が出たとします。承認額が「無制限」になっていれば、署名した瞬間にウォレット内の2,500 USDTを相手のコントラクトがいつでも引き出せる状態になります。ここで署名を拒否し、ウィンドウを閉じれば被害はありません。"],"mistakes":["検索結果の一番上に出た広告リンクを公式サイトだと思い込むこと。","「至急」「凍結」などの言葉に焦って、メール内のリンクからログインすること。","ウォレットの承認画面の内容を読まずに「確認」を押すこと。"],"faq":[{"q":"フィッシングサイトにログインしてしまったらどうすればよいですか？","a":"すぐに公式サイトからパスワードを変更し、2FAを再設定し、APIキーや出金アドレスに不審な変更がないか確認します。取引所のサポートにも連絡しましょう。"},{"q":"偽サイトでウォレットを接続しただけなら大丈夫ですか？","a":"接続だけでは通常資産は動きませんが、その後に承認や署名をしていれば危険です。署名した場合は承認を取り消すか、資産を新しいウォレットに移しましょう。"}],"title":"フィッシング詐欺とは？暗号資産での手口と対策","description":"暗号資産のフィッシング詐欺の典型的な手口、偽サイトや偽承認の見分け方、被害に遭ったときにすぐやるべきことを解説します。","related":[["anti-phishing-code","フィッシング対策コード","フィッシング対策コードとは、取引所から届く正規のメールに利用者が設定した合言葉を表示させ、偽メールと見分けやすくする機能です。"],["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。"],["token-approval","トークン承認（Approve・アローワンス）","トークン承認とは、DEXなどのスマートコントラクトに、あなたのウォレットから特定のトークンを指定量まで引き出す権限を与える操作です。"],["address-poisoning","アドレスポイズニング","アドレスポイズニングとは、本物の送金先とよく似たアドレスから少額や0円の取引を送りつけ、取引履歴から偽アドレスをコピーさせて誤送金を誘う詐欺です。"],["pig-butchering-scam","豚の屠殺詐欺（ピッグブッチャリング）","豚の屠殺詐欺とは、SNSやマッチングアプリで時間をかけて信頼関係を築いた後、偽の投資サイトやアプリに暗号資産を送金させてだまし取る詐欺です。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"本物の扉を見極める：やみくもに口座開設しないこと"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"ja","term":"準備金証明（プルーフ・オブ・リザーブ）","aka":["プルーフ・オブ・リザーブ","PoR","proof of reserves","準備金の証明"],"short":"準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。","body":[["2022年の大手取引所の破綻をきっかけに、多くの取引所が準備金証明を公開するようになりました。取引所は保有する",["ウォレットアドレス","wallet-address"],"を示して資産を証明し、マークルツリーという仕組みで利用者残高の合計を示します。"],["利用者は、自分の残高が集計に含まれているかを、取引所が提供する検証ページで確認できます。銘柄ごとの準備率が100%以上なら、",["預かり資産","total-value-locked"],"を上回る量を保有していることになります。"],"ただし限界もあります。多くの場合は資産側だけの証明で、取引所の借入などの負債全体までは示しません。また、ある時点のスナップショットにすぎないため、継続的な健全性を保証するものではありません。監査の範囲や頻度は取引所ごとに異なります。"],"example":["ある取引所の公開資料で、利用者のBTC残高の合計が20,000 ",["BTC","bitcoin"],"、取引所が保有を証明したBTCが21,000 BTCだったとします。準備率は21,000を20,000で割って105%です。一方でUSDTは利用者残高が10億USDT、保有証明が9億5,000万USDTなら準備率95%で、預かり分を下回ります。銘柄ごとに数字を見ることが大切です。"],"mistakes":["準備金証明があるだけで、取引所が絶対に破綻しないと考えること。","全体の準備率だけを見て、自分が保有する銘柄の準備率を確認しないこと。","公開日が古い準備金証明を、現在の状態だと思い込むこと。"],"faq":[{"q":"準備金証明は誰でも確認できますか？","a":"多くの取引所は公開ページで準備率を示し、口座を持つ利用者は自分の残高が含まれているかを検証できます。保有アドレスを公開している場合は、ブロックエクスプローラーでも確認できます。"},{"q":"準備率100%未満だとすぐに危険ですか？","a":"一時的な資産移動や集計方法の違いで下回る場合もありますが、継続的に下回るなら注意が必要です。理由の説明があるか、次回の公開でどう変わるかも確認しましょう。"}],"title":"準備金証明（PoR）とは？取引所の資産証明の見方","description":"取引所の準備金証明（プルーフ・オブ・リザーブ）の意味、準備率の見方、負債が含まれないなどの限界をわかりやすく解説します。","related":[["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"],["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。"],["insurance-fund","保険基金（インシュアランスファンド）","保険基金とは、先物取引所が強制ロスカットで証拠金を超える損失が出たときの穴埋めに使うために積み立てている資金で、自動デレバレッジの発動を防ぐ役割を持ちます。"],["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"本物の扉を見極める：やみくもに口座開設しないこと"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"ja","term":"暗号資産の運用サービス（Earn）","aka":["Earn","貸暗号資産","ステーキングサービス","セービング"],"short":"暗号資産の運用サービス（Earn）とは、取引所に預けた暗号資産を貸し出しやステーキングなどに回し、利息や報酬を受け取れる取引所の商品群のことです。","body":[["取引所の「Earn」や「運用」メニューには、いつでも引き出せるフレキシブル型、一定期間引き出せない定期型、",["ステーキング","staking"],"、",["デュアル投資","dual-investment"],"のような仕組み商品などが並んでいます。日本の国内取引所では、「貸暗号資産」や「ステーキング」という名前で提供されることが多いです。"],["利回りの源泉は、他の利用者への貸し出しの金利、",["ブロックチェーン","blockchain"],"のステーキング報酬、デリバティブ取引の収益など商品によって異なります。表示される年率（",["APR","apr-vs-apy"],"）が高いほど、何らかのリスクや条件がついていることが多いです。"],"大切なのは、預けた資産は取引所が管理しているという点です。取引所が破綻した場合のリスク、定期型の途中解約の可否、利率が変動するかどうかを、申し込む前に必ず確認しましょう。"],"example":"あなたが2,000 USDTを、年率4%のフレキシブル型に30日間預けたとします。日割りで計算すると、2,000×0.04×30÷365で約6.6 USDTの利息です。同じ2,000 USDTを年率6%の90日定期型に預けると、利息は約29.6 USDTになりますが、90日間は引き出せません。途中でまとまった資金が必要になった場合、定期型は解約できないか、解約すると利息を受け取れない条件のことがあります。フレキシブル型の利率は日々変動するのが一般的で、6%の定期型も満期までの利率が固定かどうかを確認する必要があります。","mistakes":["Earnに預けた資産を、銀行預金と同じように保護されていると考えてしまう。","高い年率に引かれて定期型に預け、必要なときに引き出せなくなる。","最初の一定額だけに高い利率が適用される条件を見落とし、全額に同じ利率がつくと思い込む。"],"faq":[{"q":"Earnの利息はいつ受け取れますか？","a":"フレキシブル型は毎日付与されることが多く、定期型は満期時にまとめて付与されることが多いです。商品ごとに異なるため、詳細ページで確認してください。"},{"q":"Earnに預けた資産はいつでも引き出せますか？","a":"フレキシブル型は原則いつでも引き出せますが、定期型やステーキングでは期間の終了やアンステーキングの待ち時間が必要な場合があります。"}],"title":"暗号資産のEarnとは？取引所の運用サービスの意味","description":"取引所の暗号資産運用サービス（Earn）の意味、フレキシブル型と定期型の違い、利回りの源泉と預ける前に確認すべきリスクを解説します。","related":[["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"],["apr-vs-apy","APRとAPYの違い（年利・年間利回り）","APRは複利を含まない単純な年利、APYは得た利息を再投資する複利効果を含めた年間利回りで、同じ金利でもAPYの方が高い数字になります。"],["dual-investment","デュアル投資（Dual Investment）","デュアル投資とは、あらかじめ決めた価格（ターゲット価格）と期日を設定し、期日の価格に応じて元本と利息を暗号資産かステーブルコインのどちらかで受け取る仕組み商品です。"],["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。"]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"ja","term":"P2P取引（個人間取引）","aka":["P2P","C2C","個人間取引"],"short":"P2P取引とは、取引所が仲介役となり、利用者同士が銀行振込などの法定通貨とUSDTなどの暗号資産を直接交換する取引方法です。","body":[["海外の大手取引所の多くがP2P取引の仕組みを提供しています。売り手が出した広告から条件の合う相手を選ぶと、取引所が売り手の",["暗号資産","cryptocurrency"],"を一時的に預かり（エスクロー）、買い手の支払いが確認されると暗号資産が引き渡されます。"],"P2Pは、取引所が対応していない支払い方法や通貨でも暗号資産を手に入れられる手段として使われています。一方で、支払いを済ませていないのに「支払い済み」を押す、第三者名義で振り込む、取引所の外でやり取りしようとする、といったトラブルや詐欺が起こりやすい分野でもあります。","安全に使うには、取引件数や完了率の高い相手を選び、本人名義の口座からのみ支払い、やり取りは必ず取引所のチャット内で行うことが基本です。日本の居住者の場合、利用できるかどうかは取引所の規約によって異なります。"],"example":["あなたが売り手として500 USDTを1 ",["USDT","usdt"],"＝152円で売る広告を出し、買い手が76,000円を振り込むとします。注文が成立すると、500 USDTはエスクローで保護されます。買い手が「支払い済み」を押しても、あなたが自分の銀行口座で76,000円の入金と、振込人の名義が買い手のKYC名義と一致していることを確認するまで、USDTを解放してはいけません。名義が違う入金だった場合は、受け取った金額を返金したうえで取引所の",["サポート","support-and-resistance"],"に相談し、取引をキャンセルするのが安全です。"],"mistakes":["相手が「支払い済み」を押しただけで、自分の口座への入金を確認せずに暗号資産を解放してしまう。","相場より明らかに安い価格の広告や、チャット外の連絡先に誘導してくる相手と取引する。","第三者名義からの振込を受け入れ、後で口座が凍結されるトラブルに巻き込まれる。"],"faq":[{"q":"P2P取引は安全ですか？","a":"エスクローがあるため仕組み上の保護はありますが、詐欺のリスクはゼロではありません。入金の確認、名義の一致、取引所内でのやり取りを徹底することが大切です。"},{"q":"P2PとC2Cは同じ意味ですか？","a":"はい、どちらも利用者同士が直接取引する仕組みを指します。取引所によって呼び方が違います。"}],"title":"P2P取引とは？個人間取引の仕組みと安全な使い方","description":"P2P（C2C）取引の意味とエスクローの仕組み、よくある詐欺の手口、入金確認や名義確認など安全に取引するためのポイントを解説します。","related":[["fiat-on-ramp","法定通貨オンランプ（入金ルート）","法定通貨オンランプとは、円やドルなどの法定通貨を暗号資産に交換するための入口となるサービスや手段のことで、銀行振込、クレジットカード、P2P取引などがあります。"],["usdt","USDT（テザー）","USDT（テザー）とは、Tether社が発行する米ドル連動型のステーブルコインで、暗号資産取引の基軸通貨として最も広く使われているもののひとつです。"],["pig-butchering-scam","豚の屠殺詐欺（ピッグブッチャリング）","豚の屠殺詐欺とは、SNSやマッチングアプリで時間をかけて信頼関係を築いた後、偽の投資サイトやアプリに暗号資産を送金させてだまし取る詐欺です。"],["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"最初の入金：資金はどこから来て、どこへ入るのか？"},"coin":null,"tool":null,"cta":true}});
